import shlex

def handle(query, state):
    """Simulate a web-based network ping utility.
    The user supplies a 'host' parameter and the tool 'pings' it by running a
    simulated shell command.  The in-memory shell executor is vulnerable to
    OS command injection via the pipe character.
    """
    host = (query.get("host") or ["127.0.0.1"])[0]

    files = state.get("files", {})
    hosts_db = state.get("hosts", {})

    def _run_cmd(cmd_str):
        """Execute a single command against in-memory state."""
        cmd_str = cmd_str.strip()
        if not cmd_str:
            return ""
        try:
            parts = shlex.split(cmd_str)
        except ValueError:
            return "[parse error]"
        if not parts:
            return ""
        prog = parts[0]
        args = parts[1:]

        if prog == "ping":
            target = args[0] if args else ""
            info = hosts_db.get(target)
            if info is None:
                return (
                    f"PING {target}: Network unreachable\n"
                    "--- ping statistics ---\n"
                    "4 packets transmitted, 0 received, 100% packet loss"
                )
            return (
                f"PING {target} ({info['ip']}): 56 data bytes\n"
                f"64 bytes from {info['ip']}: icmp_seq=0 ttl=64 time={info['ms']} ms\n"
                f"64 bytes from {info['ip']}: icmp_seq=1 ttl=64 time={info['ms']} ms\n"
                "--- ping statistics ---\n"
                f"4 packets transmitted, 4 received, 0% packet loss"
            )
        elif prog == "cat":
            path = args[0] if args else ""
            content = files.get(path)
            if content is None:
                return f"cat: {path}: No such file or directory"
            return content
        elif prog == "echo":
            return " ".join(args)
        elif prog == "ls":
            path = args[0] if args else "/"
            entries = set()
            for fp in files:
                if fp.startswith(path.rstrip("/") + "/"):
                    remainder = fp[len(path.rstrip("/")) + 1:]
                    top = remainder.split("/")[0]
                    entries.add(top)
            return "\n".join(sorted(entries)) if entries else ""
        elif prog == "id":
            return "uid=33(www-data) gid=33(www-data) groups=33(www-data)"
        elif prog == "whoami":
            return "www-data"
        else:
            return f"{prog}: command not found"

    def _eval_pipeline(pipeline_str):
        """Execute a pipe-separated sequence of commands.
        The 'pipe' here is implemented naively: each segment runs independently
        and their outputs are concatenated — intentionally vulnerable to injection.
        A semicolon also works as a separator (defence not implemented).
        """
        segments = []
        current = []
        in_sq = False
        in_dq = False
        for ch in pipeline_str:
            if ch == "'" and not in_dq:
                in_sq = not in_sq
                current.append(ch)
            elif ch == '"' and not in_sq:
                in_dq = not in_dq
                current.append(ch)
            elif ch == "|" and not in_sq and not in_dq:
                segments.append("".join(current))
                current = []
            elif ch == ";" and not in_sq and not in_dq:
                segments.append("".join(current))
                current = []
            else:
                current.append(ch)
        segments.append("".join(current))

        outputs = []
        for seg in segments:
            out = _run_cmd(seg)
            if out:
                outputs.append(out)
        return "\n".join(outputs)

    # Build the shell command the ping tool would execute.
    # An attacker can append additional commands after a pipe or semicolon.
    cmd = f"ping {host}"
    output = _eval_pipeline(cmd)

    body = (
        "<html><head><title>Network Ping Tool</title></head><body>"
        "<h1>Network Ping Utility</h1>"
        f"<p>Pinging host: <code>{host}</code></p>"
        "<pre>" + output + "</pre>"
        "</body></html>"
    )
    return 200, {"Content-Type": "text/html"}, body
